#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const int INF = 0x3f3f3f3f;

int N, T;
char A[15][15], B[15][15];
int id[15][15], node_cnt;
int sx, sy;
const int dr[4] = {0, 0, 1, -1};
const int dc[4] = {1, -1, 0, 0};

bool valid(int r, int c) {
    return r >= 0 && c >= 0 && r < N && c < N && A[r][c] >= '0' && A[r][c] <= '9';
}

struct Edge {
    int to, cap, rev;
    Edge(int t, int c, int r) : to(t), cap(c), rev(r) {}
};

vector<Edge> g[500];
int level[500], iter[500];

void add_edge(int u, int v, int c) {
    g[u].emplace_back(v, c, g[v].size());
    g[v].emplace_back(u, 0, g[u].size() - 1);
}

void bfs(int r, int c) {
    if (B[r][c]) {
        add_edge(id[r][c] + node_cnt, 2 * node_cnt + 1, B[r][c] - '0');
    }
    if (A[r][c] == '0') return;

    add_edge(0, id[r][c], A[r][c] - '0');
    if (B[r][c]) {
        add_edge(id[r][c], id[r][c] + node_cnt, 10);
    }

    int sr = r, sc = c;
    queue<int> q1r, q1c, q2r, q2c;
    q1r.push(r); q1c.push(c);
    q2r.push(sx); q2c.push(sy);

    vector<vector<int>> d1(N, vector<int>(N, -1));
    vector<vector<int>> d2(N, vector<int>(N, -1));
    d1[r][c] = 0;
    d2[sx][sy] = 0;

    while (!q1r.empty()) {
        int sz = q1r.size();
        for (int i = 0; i < sz; ++i) {
            int ur = q1r.front(); q1r.pop();
            int uc = q1c.front(); q1c.pop();
            if (d2[ur][uc] >= 0) continue;
            for (int k = 0; k < 4; ++k) {
                int nr = ur + dr[k], nc = uc + dc[k];
                if (valid(nr, nc) && d1[nr][nc] == -1) {
                    d1[nr][nc] = d1[ur][uc] + 1;
                    if (d1[nr][nc] > T) break;
                    if (d2[nr][nc] >= 0) continue;
                    q1r.push(nr); q1c.push(nc);
                    if (B[nr][nc] != '0') {
                        add_edge(id[sr][sc], id[nr][nc] + node_cnt, 10);
                    }
                }
            }
        }

        sz = q2r.size();
        for (int i = 0; i < sz; ++i) {
            int ur = q2r.front(); q2r.pop();
            int uc = q2c.front(); q2c.pop();
            for (int k = 0; k < 4; ++k) {
                int nr = ur + dr[k], nc = uc + dc[k];
                if (valid(nr, nc) && d2[nr][nc] == -1) {
                    d2[nr][nc] = d2[ur][uc] + 1;
                    q2r.push(nr); q2c.push(nc);
                }
            }
        }
    }
}

bool build_level() {
    memset(level, -1, sizeof(level));
    queue<int> q;
    q.push(0);
    level[0] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const auto& e : g[u]) {
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[2 * node_cnt + 1] != -1;
}

int dfs(int u, int flow) {
    if (u == 2 * node_cnt + 1) return flow;
    for (int& i = iter[u]; i < g[u].size(); ++i) {
        Edge& e = g[u][i];
        if (e.cap > 0 && level[e.to] == level[u] + 1) {
            int pushed = dfs(e.to, min(flow, e.cap));
            if (pushed > 0) {
                e.cap -= pushed;
                g[e.to][e.rev].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int max_flow() {
    int result = 0;
    while (build_level()) {
        memset(iter, 0, sizeof(iter));
        int pushed;
        while ((pushed = dfs(0, INF)) > 0) {
            result += pushed;
        }
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    for (int i = 0; i < N; ++i) cin >> A[i];
    for (int i = 0; i < N; ++i) cin >> B[i];

    memset(id, -1, sizeof(id));
    node_cnt = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (A[i][j] == 'Z') {
                sx = i; sy = j;
            } else if (valid(i, j)) {
                id[i][j] = ++node_cnt;
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (valid(i, j)) {
                bfs(i, j);
            }
        }
    }

    cout << max_flow() << '\n';
    return 0;
}
